"use client"; import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"; import { api } from "@/lib/api/services"; import { LoadingState, EmptyState, ErrorState } from "@/components/PageStates"; import { Button } from "@/components/ui/button"; import { Input } from "@/components/ui/input"; import { Label } from "@/components/ui/label"; import { Badge } from "@/components/ui/badge"; import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card"; import { formatDate } from "@/lib/utils"; import Link from "next/link"; import { useState } from "react";
export default function Dashboard(){const me=useQuery({queryKey:["me"],queryFn:api.me});const ws=useQuery({queryKey:["workspaces"],queryFn:api.workspaces});const docs=useQuery({queryKey:["documents"],queryFn:()=>api.documents("?limit=100")});const proj=useQuery({queryKey:["projects"],queryFn:api.projects});const res=useQuery({queryKey:["resumes"],queryFn:api.resumes});const pf=useQuery({queryKey:["portfolios"],queryFn:api.portfolios});
 if(me.isLoading||ws.isLoading) return <LoadingState/>; const err=me.error||ws.error; if(err) return <ErrorState message={err instanceof Error?err.message:"Failed to load dashboard"} onRetry={()=>me.refetch()}/>;
 return <div><h1 className="text-2xl font-semibold tracking-tight">Dashboard</h1><p className="mt-1 text-sm text-zinc-400">Welcome{me.data?.email?` ${me.data.email}`:""} — here is where your work stands.</p>
 <div className="mt-6 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[["Workspaces",ws.data?.length??0,"/app/workspaces"],["Documents",docs.data?.length??0,"/app/documents"],["Projects",proj.data?.length??0,"/app/projects"],["Resumes / Portfolios",`${res.data?.length??0} / ${pf.data?.length??0}`,"/app/resume"]].map(([l,v,h])=><Link key={l as string} href={h as string}><Card><CardContent className="pt-5"><p className="text-sm text-zinc-400">{l}</p><p className="mt-2 text-3xl font-semibold">{v}</p></CardContent></Card></Link>)}</div>
 <div className="mt-8 grid gap-6 lg:grid-cols-2"><Card><CardHeader><CardTitle>Recent workspaces</CardTitle></CardHeader><CardContent>{!ws.data?.length?<EmptyState title="No workspaces yet" desc="Create one to upload research and start asking cited questions." action={<Link href="/app/workspaces"><Button size="sm">Create workspace</Button></Link>}/>:<ul className="divide-y divide-white/[0.06]">{ws.data.slice(0,5).map(x=><li key={x.id} className="flex items-center justify-between py-3"><Link href={`/app/workspaces/${x.id}`} className="font-medium hover:underline">{x.name}</Link><span className="text-xs text-zinc-500">{formatDate(x.created_at)}</span></li>)}</ul>}</CardContent></Card>
 <Card><CardHeader><CardTitle>Your journey</CardTitle></CardHeader><CardContent><ol className="space-y-3 text-sm">{["Research — upload and chat with documents","Project — turn findings into proof-of-work","Resume — attach verified records, export PDF","Portfolio — publish and share with recruiters","Career AI — close skill gaps with a plan"].map((s,i)=><li key={s} className="flex gap-3"><span className="font-mono text-xs text-indigo-300">{String(i+1).padStart(2,"0")}</span><span className="text-zinc-300">{s}</span></li>)}</ol><Link href="/app/career-ai"><Button className="mt-5" size="sm">Open Career AI</Button></Link></CardContent></Card></div></div>;}
